<script setup>
import {ref,reactive,computed,onMounted,onUnmounted} from 'vue'
import {api} from './api'
const props=defineProps({language:String,idle:Boolean})
const emit=defineEmits(['status','busy'])
const tr=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const state=ref(null),reachable=ref(null),error=ref(''),busy=ref(false),open=ref(false),networks=ref([]),now=ref(Date.now())
const form=reactive({ssid:'',password:'',security:'wpa-psk'})
const pending=computed(()=>state.value?.pending?.temporary?state.value.pending:null)
const wifi=computed(()=>state.value?.interfaces.find(i=>i.interface==='wlan0'))
const ethernet=computed(()=>state.value?.interfaces.find(i=>i.interface==='eth0'))
const remaining=computed(()=>Math.max(0,Math.ceil(((pending.value?.expires_at||0)*1000-now.value)/1000)))
const request=(path,options={})=>api('/api/commissioning/network/'+path,options)
function update(value){state.value=value;emit('status',value)}
async function refresh(){update(await request('status'))}
async function check(){reachable.value=(await api('/api/commissioning/internet')).reachable}
async function run(fn){if(busy.value)return;busy.value=true;emit('busy',true);error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false;emit('busy',false)}}
async function connect(){try{update(await request('temporary-connect',{method:'POST',body:JSON.stringify(form)}))}finally{form.password=''}}
async function confirm(){update(await request('confirm',{method:'POST',body:JSON.stringify({id:pending.value.id})}));open.value=false;await check()}
async function disconnect(){update(await request('temporary-disconnect',{method:'POST',body:'{}'}));await check()}
async function scan(){networks.value=(await request('wifi')).networks}
function choose(event){const selected=networks.value.find(n=>n.ssid===event.target.value);if(selected)form.security=selected.security}
let timer
onMounted(()=>{run(async()=>{await refresh();await check()});timer=setInterval(()=>{now.value=Date.now();if((pending.value||state.value?.temporary_wifi)&&!busy.value&&!document.hidden)run(refresh)},2000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="card content temporary-internet"><h2>{{tr('Временный интернет для установки','Sozlash uchun vaqtinchalik internet','Temporary internet for setup')}}</h2>
<p class="internet-status" role="status">{{reachable===null?tr('Проверяем сервер активации…','Faollashtirish serveri tekshirilmoqda…','Checking activation server…'):reachable?tr('Сервер активации доступен','Faollashtirish serveri mavjud','Activation server is reachable'):tr('Нет связи с сервером активации. Можно подключить точку доступа телефона или выбрать офлайн-активацию ниже.','Faollashtirish serveri bilan aloqa yo‘q. Telefon internetiga ulaning yoki quyida oflayn faollashtirishni tanlang.','Activation server is unreachable. Connect a phone hotspot or use offline activation below.')}}</p>
<p>{{tr('Ethernet сохраняется для связи между постами. Временный Wi-Fi подключается отдельно на каждом устройстве. Пароль не сохраняется на диск; подключение действует до 2 часов и не подключается автоматически после перезагрузки.','Postlar orasidagi aloqa uchun Ethernet saqlanadi. Har bir qurilma vaqtinchalik Wi-Fi ga alohida ulanadi. Parol diskka yozilmaydi; ulanish 2 soatgacha ishlaydi va qayta yoqilganda avtomatik ulanmaydi.','Ethernet stays connected for local stations. Connect each device separately. The password is not saved to disk; temporary access lasts up to 2 hours and will not reconnect after reboot.')}}</p>
<p v-if="ethernet?.address" class="muted">{{tr('Адрес через роутер мойки','Yuvish routeridagi manzil','Site router address')}}: <strong>http://{{ethernet.address}}/install</strong></p>
<div v-if="error" class="message error" role="alert">{{error}}</div>
<template v-if="pending"><p>{{tr('Ожидаем подключение к Wi-Fi. Подтвердите до истечения времени:','Wi-Fi ulanishi kutilmoqda. Vaqt tugashidan oldin tasdiqlang:','Waiting for Wi-Fi. Confirm before timeout:')}} <strong>{{remaining}} s</strong></p><p>{{wifi?.ssid}} · {{wifi?.address||'…'}}</p><p v-if="state.temporary_subnet_conflict" class="message error">{{tr('Подсеть телефона совпадает с Ethernet. Отмените подключение и измените подсеть телефона или используйте офлайн-активацию.','Telefon va Ethernet tarmoqlari bir xil. Ulanishni bekor qilib, telefon tarmog‘ini o‘zgartiring yoki oflayn faollashtiring.','The hotspot subnet overlaps Ethernet. Cancel and change the hotspot subnet or use offline activation.')}}</p><div class="actions"><button class="primary" :disabled="busy||!wifi?.connected||!wifi?.gateway||state.temporary_subnet_conflict" @click="run(confirm)">{{tr('Подтвердить временный Wi-Fi','Vaqtinchalik Wi-Fi ni tasdiqlash','Confirm temporary Wi-Fi')}}</button><button class="quiet" :disabled="busy" @click="run(disconnect)">{{tr('Отменить подключение','Ulanishni bekor qilish','Cancel connection')}}</button></div></template>
<template v-else-if="state?.temporary_wifi"><p><strong>{{tr('Временный Wi-Fi подключён','Vaqtinchalik Wi-Fi ulangan','Temporary Wi-Fi connected')}}:</strong> {{state.temporary_wifi.ssid}}</p><div class="actions"><button class="quiet" :disabled="busy" @click="run(check)">{{tr('Проверить интернет','Internetni tekshirish','Check internet')}}</button><button class="quiet" :disabled="busy||!idle" @click="run(disconnect)">{{tr('Отключить и забыть временный Wi-Fi','Vaqtinchalik Wi-Fi ni uzish va unutish','Disconnect and forget temporary Wi-Fi')}}</button></div></template>
<template v-else><div class="actions"><button class="quiet" :disabled="busy||!idle||!wifi" @click="open=!open">{{tr('Подключить Wi-Fi телефона','Telefon Wi-Fi siga ulanish','Connect phone Wi-Fi')}}</button><button class="quiet" :disabled="busy" @click="run(check)">{{tr('Проверить интернет','Internetni tekshirish','Check internet')}}</button></div>
<p v-if="state&&!wifi" class="muted">{{tr('Wi-Fi адаптер не найден. Используйте Ethernet с интернетом или офлайн-активацию.','Wi-Fi adapteri topilmadi. Internetli Ethernet yoki oflayn faollashtirishdan foydalaning.','Wi-Fi adapter not found. Use Ethernet internet or offline activation.')}}</p>
<form v-if="open" @submit.prevent="run(connect)"><p>{{tr('Включите точку доступа на телефоне. Если сеть не видна, попробуйте диапазон 2,4 ГГц.','Telefonda kirish nuqtasini yoqing. Tarmoq ko‘rinmasa, 2,4 GHz diapazonini sinang.','Enable the phone hotspot. If it is not visible, try the 2.4 GHz band.')}}</p><button type="button" class="quiet" :disabled="busy" @click="run(scan)">{{tr('Найти сети','Tarmoqlarni qidirish','Find networks')}}</button><label v-if="networks.length">{{tr('Найденные сети','Topilgan tarmoqlar','Available networks')}}<select :aria-label="tr('Найденные сети','Topilgan tarmoqlar','Available networks')" v-model="form.ssid" @change="choose"><option value="">—</option><option v-for="n in networks" :key="n.ssid" :value="n.ssid" :disabled="n.security==='unsupported'">{{n.ssid}} · {{n.signal}}%</option></select></label>
<div class="fields"><label>{{tr('Название точки доступа','Kirish nuqtasi nomi','Hotspot name')}}<input v-model="form.ssid" maxlength="32" autocomplete="off" required /></label><label>{{tr('Пароль точки доступа','Kirish nuqtasi paroli','Hotspot password')}}<input v-model="form.password" type="password" minlength="8" maxlength="63" autocomplete="off" required /></label><label>{{tr('Защита сети','Tarmoq himoyasi','Security')}}<select v-model="form.security"><option value="wpa-psk">WPA2 Personal</option><option value="sae">WPA3 Personal</option></select></label></div><button class="primary" :disabled="busy||!idle">{{tr('Подключить временно','Vaqtincha ulanish','Connect temporarily')}}</button></form></template>
</section></template>
<style scoped>.temporary-internet{padding:28px;margin:24px 0}.temporary-internet p{line-height:1.6}.temporary-internet form{display:grid;gap:20px;margin-top:24px}.temporary-internet .actions{display:flex;flex-wrap:wrap;gap:14px}.temporary-internet label{display:grid;gap:10px}.internet-status{font-weight:600}</style>
